(define subset-p {(list symbol) --> (list symbol) --> boolean}
  [] _ -> true
  [X | Xs] B -> (and (element? X B) (subset-p Xs B)))
(define same-set {(list symbol) --> (list symbol) --> boolean}
  A B -> (and (= (length A) (length B)) (subset-p A B)))

